  addBookCopy(callNo: string, barcode: string, location: string): boolean {
    /*Definition Start*/
    let book: Book = l({
      logic: () =>
        getRepository(Book).find(
          (b: Book) =>
            l({
              logic: () => b.CallNo === callNo,
              description: "b.CallNo=callNo",
            }).build().pass,
        ),
      description: "Book.allInstance()->any(b:Book|b.CallNo=callNo)",
    }).build().pass;
    let dup: BookCopy = l({
      logic: () =>
        getRepository(BookCopy).find(
          (bc: BookCopy) =>
            l({
              logic: () => bc.Barcode === barcode,
              description: "bc.Barcode=barcode",
            }).build().pass,
        ),
      description:
        "BookCopy.allInstance()->any(bc:BookCopy|bc.Barcode=barcode)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(book) === false,
        description: "book.oclIsUndefined()=false",
      })
        .and({
          logic: () => StandardOPs.oclIsUndefined(dup) === true,
          description: "dup.oclIsUndefined()=true",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newCopy: BookCopy;
    return l({
      execute: () => (newCopy = new BookCopy()),
      description: "newCopy.oclIsNew()",
    })
      .and({
        execute: () => (newCopy.Barcode = barcode),
        description: "newCopy.Barcode=barcode",
      })
      .and({
        execute: () => (newCopy.Location = location),
        description: "newCopy.Location=location",
      })
      .and({
        execute: () => (newCopy.Status = CopyStatus.AVAILABLE),
        description: "newCopy.Status=CopyStatus::AVAILABLE",
      })
      .and({
        execute: () => (newCopy.IsReserved = false),
        description: "newCopy.IsReserved=false",
      })
      .and({
        execute: () => (newCopy.BookBelongs = book),
        description: "newCopy.BookBelongs=book",
      })
      .and({
        execute: () => book.Copys.push(newCopy),
        description: "book.Copys->includes(newCopy)",
      })
      .and({
        execute: () => getRepository(BookCopy).push(newCopy),
        description: "BookCopy.allInstance()->includes(newCopy)",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
